use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            forall |i: nat| 0 <= i < result.len() ==> result[i] == 1,
    {
        let n = a.len() as nat; // Get the length of the input vector
        let mut result: Vec<i32> = Vec::new(); // Initialize the output vector

        let mut idx: nat = 0; // Initialize the loop counter
        while idx < n
            invariant
                idx <= n,
                result.len() == idx,
                forall |j: nat| 0 <= j < idx ==> result[j] == 1,
            decreases n - idx,
        {
            result.push(1); // Add 1 to the output vector
            idx = idx + 1; // Increment the loop counter
        }

        result // Return the constructed vector
    }
}

